SELECT SUM(CASE WHEN c.country_iso_code = 'US' THEN pc.country_id ELSE 0 END) * 100.0 / COUNT(pc.country_id) AS percentage
FROM production_country AS pc
JOIN country AS c ON c.country_id = pc.country_id;

